-- Identity, tenancy and access control.
--
-- Conventions used across all migrations:
--   * Primary keys are UUIDv7 values generated by the application (time ordered).
--   * Every tenant-owned table has tenant_id and exposes UNIQUE (tenant_id, id) so
--     children can reference it with a composite foreign key. That makes it
--     impossible at the database level to attach a row to another tenant's parent.
--   * Mutable business records carry created_at/created_by/updated_at/updated_by
--     and a version column for optimistic locking.

CREATE TABLE tenants (
    id                 uuid PRIMARY KEY,
    name               text        NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    status             text        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'DELETED')),
    max_active_jobs    integer     NOT NULL DEFAULT 10 CHECK (max_active_jobs >= 0),
    max_snapshot_bytes bigint      NOT NULL DEFAULT 104857600 CHECK (max_snapshot_bytes > 0),
    created_at         timestamptz NOT NULL,
    created_by         uuid,
    updated_at         timestamptz NOT NULL,
    updated_by         uuid,
    version            bigint      NOT NULL DEFAULT 0
);

CREATE TABLE users (
    id           uuid PRIMARY KEY,
    issuer       text        NOT NULL,
    subject      text        NOT NULL,
    email        text,
    display_name text,
    status       text        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED')),
    created_at   timestamptz NOT NULL,
    updated_at   timestamptz NOT NULL,
    last_seen_at timestamptz,
    version      bigint      NOT NULL DEFAULT 0,
    UNIQUE (issuer, subject)
);
CREATE INDEX users_email_idx ON users (lower(email));

-- The owner of a tenant is the user who created it; billing and tenant-wide
-- settings hang off this later.
ALTER TABLE tenants ADD COLUMN owner_user_id uuid REFERENCES users (id);

CREATE TABLE organizations (
    id         uuid PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES tenants (id),
    name       text        NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    slug       text        NOT NULL CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
    status     text        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'ARCHIVED')),
    created_at timestamptz NOT NULL,
    created_by uuid        NOT NULL REFERENCES users (id),
    updated_at timestamptz NOT NULL,
    updated_by uuid        NOT NULL REFERENCES users (id),
    version    bigint      NOT NULL DEFAULT 0,
    UNIQUE (slug),
    UNIQUE (tenant_id, id)
);

CREATE TABLE workspaces (
    id              uuid PRIMARY KEY,
    tenant_id       uuid        NOT NULL,
    organization_id uuid        NOT NULL,
    name            text        NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    slug            text        NOT NULL CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
    created_at      timestamptz NOT NULL,
    created_by      uuid        NOT NULL REFERENCES users (id),
    updated_at      timestamptz NOT NULL,
    updated_by      uuid        NOT NULL REFERENCES users (id),
    version         bigint      NOT NULL DEFAULT 0,
    FOREIGN KEY (tenant_id, organization_id) REFERENCES organizations (tenant_id, id),
    UNIQUE (organization_id, slug),
    UNIQUE (tenant_id, id)
);

-- System-defined permissions and roles. Custom roles per organization come later;
-- the organization_id column is reserved for them and NULL for built-in roles.
CREATE TABLE permissions (
    code        text PRIMARY KEY,
    description text NOT NULL
);

CREATE TABLE roles (
    id              text PRIMARY KEY,
    name            text NOT NULL,
    description     text NOT NULL,
    rank            integer NOT NULL,
    organization_id uuid REFERENCES organizations (id)
);

CREATE TABLE role_permissions (
    role_id         text NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
    permission_code text NOT NULL REFERENCES permissions (code),
    PRIMARY KEY (role_id, permission_code)
);

CREATE TABLE organization_memberships (
    id              uuid PRIMARY KEY,
    tenant_id       uuid        NOT NULL,
    organization_id uuid        NOT NULL,
    user_id         uuid        NOT NULL REFERENCES users (id),
    role_id         text        NOT NULL REFERENCES roles (id),
    status          text        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'REMOVED')),
    created_at      timestamptz NOT NULL,
    created_by      uuid        NOT NULL REFERENCES users (id),
    updated_at      timestamptz NOT NULL,
    updated_by      uuid        NOT NULL REFERENCES users (id),
    version         bigint      NOT NULL DEFAULT 0,
    FOREIGN KEY (tenant_id, organization_id) REFERENCES organizations (tenant_id, id),
    UNIQUE (organization_id, user_id)
);
CREATE INDEX organization_memberships_user_idx ON organization_memberships (user_id) WHERE status = 'ACTIVE';

CREATE TABLE invitations (
    id              uuid PRIMARY KEY,
    tenant_id       uuid        NOT NULL,
    organization_id uuid        NOT NULL,
    email           text        NOT NULL,
    role_id         text        NOT NULL REFERENCES roles (id),
    token_hash      bytea       NOT NULL UNIQUE,
    status          text        NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'ACCEPTED', 'REVOKED', 'EXPIRED')),
    expires_at      timestamptz NOT NULL,
    accepted_by     uuid REFERENCES users (id),
    accepted_at     timestamptz,
    created_at      timestamptz NOT NULL,
    created_by      uuid        NOT NULL REFERENCES users (id),
    updated_at      timestamptz NOT NULL,
    updated_by      uuid        NOT NULL REFERENCES users (id),
    version         bigint      NOT NULL DEFAULT 0,
    FOREIGN KEY (tenant_id, organization_id) REFERENCES organizations (tenant_id, id)
);
CREATE UNIQUE INDEX invitations_pending_email_idx ON invitations (organization_id, lower(email)) WHERE status = 'PENDING';

-- Personal access tokens. Only the SHA-256 of the secret is stored; the prefix is
-- kept so users can recognise a token in listings.
CREATE TABLE api_tokens (
    id              uuid PRIMARY KEY,
    tenant_id       uuid        NOT NULL,
    organization_id uuid        NOT NULL,
    user_id         uuid        NOT NULL REFERENCES users (id),
    name            text        NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    token_prefix    text        NOT NULL,
    token_hash      bytea       NOT NULL UNIQUE,
    expires_at      timestamptz NOT NULL,
    revoked_at      timestamptz,
    revoked_by      uuid REFERENCES users (id),
    last_used_at    timestamptz,
    created_at      timestamptz NOT NULL,
    created_by      uuid        NOT NULL REFERENCES users (id),
    updated_at      timestamptz NOT NULL,
    updated_by      uuid        NOT NULL REFERENCES users (id),
    version         bigint      NOT NULL DEFAULT 0,
    FOREIGN KEY (tenant_id, organization_id) REFERENCES organizations (tenant_id, id)
);
CREATE INDEX api_tokens_org_idx ON api_tokens (organization_id, user_id);

-- Append-only audit trail. UPDATE and DELETE are rejected by trigger so that a
-- compromised application path cannot quietly rewrite history.
CREATE TABLE audit_events (
    id              bigserial PRIMARY KEY,
    event_id        uuid        NOT NULL UNIQUE,
    tenant_id       uuid REFERENCES tenants (id),
    organization_id uuid REFERENCES organizations (id),
    actor_type      text        NOT NULL CHECK (actor_type IN ('USER', 'API_TOKEN', 'WORKER', 'SYSTEM')),
    actor_id        uuid,
    action          text        NOT NULL,
    target_type     text,
    target_id       uuid,
    outcome         text        NOT NULL CHECK (outcome IN ('SUCCESS', 'DENIED', 'FAILURE')),
    details         jsonb       NOT NULL DEFAULT '{}'::jsonb,
    client_ip       text,
    user_agent      text,
    request_id      text,
    occurred_at     timestamptz NOT NULL
);
CREATE INDEX audit_events_org_time_idx ON audit_events (organization_id, occurred_at DESC);
CREATE INDEX audit_events_tenant_time_idx ON audit_events (tenant_id, occurred_at DESC);

CREATE FUNCTION audit_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_events is append-only';
END;
$$;

CREATE TRIGGER audit_events_no_update BEFORE UPDATE OR DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION audit_events_immutable();

